import{_ as r,o as t,c as a,ah as s}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse('{"title":"Gerichtliche Nachspiele: Karl-Heinz Grasser (Buwog-Causa)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/gericht-grasser.md","filePath":"recherche/gericht-grasser.md"}'),i={name:"recherche/gericht-grasser.md"};function n(h,e,l,o,u,c){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="gerichtliche-nachspiele-karl-heinz-grasser-buwog-causa" tabindex="-1">Gerichtliche Nachspiele: Karl-Heinz Grasser (Buwog-Causa) <a class="header-anchor" href="#gerichtliche-nachspiele-karl-heinz-grasser-buwog-causa" aria-label="Permalink to &quot;Gerichtliche Nachspiele: Karl-Heinz Grasser (Buwog-Causa)&quot;">​</a></h1><p><strong>Vom „schönsten Finanzminister“ zum erstinstanzlich Verurteilten.</strong></p><p>Karl-Heinz Grasser verkörperte den frühen Aufstieg der „Young Guns“ in der österreichischen Politik. Sein Fall ist das historische Vorbild für die moderne Verflechtung von Glanz, Macht und Korruption.</p><hr><h2 id="die-buwog-affare" tabindex="-1">Die Buwog-Affäre <a class="header-anchor" href="#die-buwog-affare" aria-label="Permalink to &quot;Die Buwog-Affäre&quot;">​</a></h2><ul><li><strong>Der Vorwurf:</strong> Schmiergeldzahlungen in Millionenhöhe beim Verkauf von 60.000 Bundeswohnungen im Jahr 2004.</li><li><strong>Das Urteil (Dezember 2020):</strong> Grasser wurde in erster Instanz zu <strong>acht Jahren Haft</strong> wegen Untreue, Bestechlichkeit und Beweismittelfälschung verurteilt.</li><li><strong>Aktueller Status (2026):</strong> Das Verfahren befindet sich in der nächsten Instanz. Grasser bestreitet alle Vorwürfe und kämpft um seine Freiheit, während die Aktenberge weiter wachsen.</li></ul><hr><h2 id="bedeutung-fur-unser-projekt" tabindex="-1">Bedeutung für unser Projekt <a class="header-anchor" href="#bedeutung-fur-unser-projekt" aria-label="Permalink to &quot;Bedeutung für unser Projekt&quot;">​</a></h2><p>Grasser ist die „Ouvertüre“ zum Horten-Mysterium. Er zeigte, dass man Macht als Lifestyle inszenieren kann, solange die Fassade hält. Er ist der geistige Vorläufer des modernen Pointillismus.</p><hr><p><em>Quellen: Erstinstanzliches Urteil LG Wien (Buwog), Berichterstattung Standard/Profil.</em></p>',11)])])}const f=r(i,[["render",n]]);export{g as __pageData,f as default};
